Here, $\phi_{1}=0^{\circ}, \phi=45^{\circ}$
\begin{array}{l}
B=\frac{\mu_{0}}{4 \pi} \cdot \frac{i}{r}\left(\sin 0^{\circ}+\sin 45^{\circ}\right)=\frac{\mu_{0}}{4 \pi} \cdot \frac{i}{\sqrt{2 l}} \\
\Rightarrow B=\frac{\sqrt{2} \mu_{0} i}{8 \pi l}
\end{array}

$I=I_{0}\left(1-e^{-t / \tau}\right)$
where $\tau \rightarrow$ time constant

\begin{array}{l}
\therefore \quad \frac{3}{4} I_{0}=I_{0}\left(1-e^{-t / \tau}\right) \\
\Rightarrow \quad \frac{3}{4}=1-e^{-t / \tau} \Rightarrow e^{-t / \tau}=\frac{1}{4} \\
\Rightarrow \quad \frac{-t}{\tau} \ln e=\ln \frac{1}{4} \Rightarrow \frac{-4}{\tau}=-2 \ln 2 \\
\Rightarrow \quad \tau=\frac{2}{\ln 2}
\end{array}
